#include "cryptoutils.h"
int main(void){const char *plain="send more money";const int key[13]={9,0,1,7,23,15,21,14,11,11,2,8,9};char p[128],c[128];cu_letters(plain,p,0);size_t n=strlen(p);for(size_t i=0;i<n;i++)c[i]='A'+cu_mod((p[i]-'A')+key[i],26);c[n]='\0';printf("Part (a) plaintext: %s\nKey stream: ",p);for(size_t i=0;i<n;i++)printf("%d%s",key[i],i+1<n?" ":"");printf("\nCiphertext: %s\n",c);const char *target="cash not needed";char t[128];cu_letters(target,t,0);if(strlen(t)!=n){puts("Target plaintext length differs from ciphertext; cannot derive same-length key stream.");return 0;}printf("Part (b) target plaintext: %s\nKey to make this ciphertext decrypt to the target: ",t);for(size_t i=0;i<n;i++)printf("%d%s",cu_mod((c[i]-'A')-(t[i]-'A'),26),i+1<n?" ":"");puts("\nThis second stream is computed as (cipher - target) mod 26.");return 0;}
